1800-2023
Tiêu chuẩn IEEE cho SystemVerilog—Ngôn ngữ Thiết kế, Mô tả và Kiểm thử Phần cứng Hợp nhất

ab c;
c = '{0, 0.0}; // kiểu hằng cấu trúc được xác định từ
               // ngữ cảnh phía bên trái (c)

Các dấu ngoặc nhọn lồng nhau phải phản ánh đúng cấu trúc. Ví dụ:

ab abarr[1:0] = '{ '{1, 1.0}, '{2, 2.0}};

Cách viết thay thế kiểu ngôn ngữ C '{1, 1.0, 2, 2.0} cho ví dụ trước là không được phép.

Hằng cấu trúc cũng có thể sử dụng tên thành viên và giá trị, hoặc sử dụng kiểu dữ liệu và giá trị mặc định (xem 10.9.2):

c = '{a:0, b:0.0};              // tên thành viên và giá trị cho thành viên đó
c = '{default:0};               // tất cả các phần tử của cấu trúc c được đặt thành 0
d = ab'{int:1, shortreal:1.0};  // kiểu dữ liệu và giá trị mặc định cho tất cả
                               // các thành viên thuộc kiểu đó

Khi một mảng các cấu trúc được khởi tạo, các dấu ngoặc nhọn lồng nhau phải phản ánh mảng và cấu trúc. Ví dụ:

ab abarr[1:0] = '{ '{1, 1.0}, '{2, 2.0}};

Các toán tử lặp có thể được sử dụng để gán giá trị cho đúng số lượng thành viên. Cặp dấu ngoặc nhọn bên trong trong một phép lặp sẽ bị loại bỏ.

struct {int X,Y,Z;} XYZ = '{3{1}};
typedef struct {int a,b[4];} ab_t;
int a,b,c;
ab_t v1[1:0] [2:0];
v1 = '{2{'{3{'{a,'{2{b,c}}}}}}}};

/* khai triển thành '{ '{3{ '{ a, '{2{ b, c } } } } },
                       '{3{ '{ a, '{2{ b, c } } } } }
                     } */

/* khai triển thành '{ '{ '{ a, '{2{ b, c } } },
                       '{ a, '{2{ b, c } } },
                       '{ a, '{2{ b, c } } }
                     },
                     '{ '{ a, '{2{ b, c } } },
                       '{ a, '{2{ b, c } } },
                       '{ a, '{2{ b, c } } }
                     } */

/* khai triển thành '{ '{ '{ a, '{ b, c, b, c } },
                       '{ a, '{ b, c, b, c } },
                       '{ a, '{ b, c, b, c } }
                     },
                     '{ '{ a, '{ b, c, b, c } },
                       '{ a, '{ b, c, b, c } },
                       '{ a, '{ b, c, b, c } }
                     } */

